const $=id=>document.getElementById(id);let cmcTimer;let state=null,nightOnly=false,selected=0,request=0,horizon=24,units='imperial';const rad=180/Math.PI;let imagingRun=0;
const escapeText=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const finite=v=>typeof v==='number'&&Number.isFinite(v);const value=v=>finite(v)?v:null;const display=(v,suffix='',digits=0)=>finite(v)?v.toFixed(digits)+suffix:'null';
function temperature(v){return display(finite(v)?units==='imperial'?v*9/5+32:v:null,units==='imperial'?'°F':'°C',1)}function wind(v){return display(finite(v)?units==='imperial'?v/1.609344:v:null,units==='imperial'?' mph':' km/h',1)}
function precipAmount(v){return display(NightwatchWeather.precipitation(v,units),units==='imperial'?' in':' mm',units==='imperial'?3:1)}
function dewAdvice(h){if(!h||![h.temp,h.dew,h.humidity].every(finite))return {use:null,text:'Required temperature, dew point, or humidity data is unavailable. Recommendation: null.'};const spread=h.temp-h.dew;return spread<=3||h.humidity>=85?{use:true,text:'Use a dew heater at low power and monitor your optics. The forecast meets the humidity ≥85% or temperature/dew-point spread ≤3°C (5.4°F) threshold.'}:{use:false,text:'A dew heater is not indicated by the forecast thresholds at this hour. Keep it available and inspect your optics: radiative cooling can still cause dew.'}}
async function json(url){const r=await fetch(url,{signal:AbortSignal.timeout(18000)});if(!r.ok)throw Error('Service returned '+r.status);return r.json()}
function fmt(d,opts={weekday:'short',hour:'numeric',minute:'2-digit'}){if(!d||!Number.isFinite(+d))return 'null';return new Intl.DateTimeFormat('en-US',{timeZone:state.zone,...opts}).format(d)}
async function load(lat,lon,name){const token=++request;imagingRun++;if(state)state.imagingRunning=false;$('status').textContent='Updating local forecast…';try{const data=await json('https://api.open-meteo.com/v1/forecast?latitude='+lat+'&longitude='+lon+'&hourly=temperature_2m,dew_point_2m,relative_humidity_2m,cloud_cover,wind_speed_10m,precipitation_probability,precipitation&forecast_days=5&timezone=auto&timeformat=unixtime');if(token!==request)return;const now=new Date(),dates=NightwatchTime.periods(now,data.timezone||'UTC',72);const byTime=new Map((data.hourly?.time||[]).map((t,i)=>[t*1000,i]));const hours=dates.map(date=>{const i=byTime.get(+date),get=k=>i===undefined?null:value(data.hourly[k]?.[i]);return {date,sun:SunCalc.getPosition(date,lat,lon).altitude*rad,moonAlt:SunCalc.getMoonPosition(date,lat,lon).altitude*rad,moonIllum:SunCalc.getMoonIllumination(date).fraction,cloud:get('cloud_cover'),humidity:get('relative_humidity_2m'),wind:get('wind_speed_10m'),temp:get('temperature_2m'),dew:get('dew_point_2m'),rain:get('precipitation_probability'),precip:get('precipitation'),transparency:null,seeing:null,score:null}});hours.forEach(h=>h.score=NightwatchScore.infer(h));state={lat,lon,name,zone:data.timezone||'UTC',hours,moon:SunCalc.getMoonIllumination(now),now};selected=0;render();renderLocalSky();loadLocalSky(state);const missing=hours.some(h=>[h.cloud,h.humidity,h.wind,h.temp,h.dew,h.rain,h.precip].some(v=>v===null));$('status').textContent=missing?'Some forecast values are unavailable and shown as null.':'';try{localStorage.setItem('nightwatch-location',JSON.stringify({lat,lon,name}))}catch{}}catch(e){if(token===request){$('status').textContent='Couldn’t update the forecast. Try again. '+(state?'Previous location and update time remain displayed.':'');if(!state){$('updated').textContent='Live forecast unavailable';$('headline').textContent='The sky will be here.';$('summary').textContent='Search a city or use your location to try again.';}}}}
function astronomy(){const end=+state.now+horizon*3600000,samples=[];for(let t=+state.now;t<=end;t+=60000)samples.push({date:new Date(t),alt:SunCalc.getPosition(new Date(t),state.lat,state.lon).altitude*rad});let darkMinutes=0;const events=[];for(let i=1;i<samples.length;i++){if(samples[i-1].alt<-18)darkMinutes++;for(const [alt,label,icon,sub] of [[-.833,'Sunset','☀','The Sun dips below the horizon'],[-18,'Astronomical dusk','✦','True darkness begins']]){if(samples[i-1].alt>=alt&&samples[i].alt<alt)events.push({date:samples[i].date,label,icon,sub});if(samples[i-1].alt<alt&&samples[i].alt>=alt)events.push({date:samples[i].date,label:alt===-18?'Astronomical dawn':'Sunrise',icon:alt===-18?'✧':'☀',sub:alt===-18?'True darkness ends':'The Sun returns above the horizon'});}}return{darkMinutes,events}}
function nextMoonTimes(start,end,lat,lon){
 const result={rise:null,set:null},begin=+start,finish=+end;
 if(![begin,finish,lat,lon].every(Number.isFinite)||finish<=begin||Math.abs(lat)>90||Math.abs(lon)>180)return result;
 const first=new Date(begin);first.setUTCHours(0,0,0,0);
 for(let day=+first;day<finish;day+=86400000){
  const times=SunCalc.getMoonTimes(new Date(day),lat,lon,true);
  for(const key of ['rise','set']){const event=times[key];if(event&&Number.isFinite(+event)&&+event>=begin&&+event<finish&&(!result[key]||+event<+result[key]))result[key]=event;}
 }
 return result;
}
function renderCardTimes(events){
 const moon=nextMoonTimes(state.now,new Date(+state.now+horizon*3600000),state.lat,state.lon);
 const entries=[['card-sunrise','Sunrise',events.find(e=>e.label==='Sunrise')?.date],['card-sunset','Sunset',events.find(e=>e.label==='Sunset')?.date],['card-dusk','Astronomical dusk',events.find(e=>e.label==='Astronomical dusk')?.date],['card-dawn','Astronomical dawn',events.find(e=>e.label==='Astronomical dawn')?.date],['card-moonrise','Moonrise',moon.rise],['card-moonset','Moonset',moon.set]];
 for(const [id,label,date] of entries){$(id).textContent=label+': '+(date?fmt(date):'null');$(id).title=date?'Calculated for '+state.zone:'No '+label.toLowerCase()+' in the next '+horizon+' hours at this location.';}
 for(const id of ['moon-card-times','sun-card-times'])$(id).title='Next occurrences within '+horizon+' hours · '+state.zone;
}
function render(){if(!state)return;const s=state,a=astronomy();$('place').textContent=s.name;$('updated').textContent='Updated '+fmt(s.now)+' · weather forecast';$('zone').textContent=s.zone.replaceAll('_',' ')+' · local time';$('horizon-label').textContent='YOUR NEXT '+horizon+' HOURS';$('headline').innerHTML='Make time<br>for the night.';$('summary').textContent='Explore forecast clouds, humidity, and dew point alongside calculated darkness. CMC supplies selected-hour seeing and transparency where available.';const best=s.hours.slice(0,horizon).filter(h=>h.sun<-18&&finite(h.score)).sort((a,b)=>b.score-a.score)[0];$('best').textContent=best?'✧ Highest inferred dark-hour score: '+best.score+'/100 · '+fmt(best.date):'✧ No scored astronomical dark hours';$('dark').textContent='☾ '+(a.darkMinutes/60).toFixed(1)+' hours of calculated darkness';$('darkhours').textContent=(a.darkMinutes/60).toFixed(1)+' hrs';$('dark-caption').textContent='Sun below −18° · next '+horizon+' hours';renderCardTimes(a.events);$('milestone-title').textContent='Astronomy milestones · '+horizon+' hours';$('moon').textContent=display(s.moon.fraction*100,'%');const p=s.moon.phase;$('phase').textContent=(p<.03||p>.97?'New moon':p<.25?'Waxing crescent':p<.28?'First quarter':p<.48?'Waxing gibbous':p<.53?'Full moon':p<.75?'Waning gibbous':p<.78?'Last quarter':'Waning crescent')+' · at forecast start';$('events').innerHTML=a.events.length?a.events.map(e=>'<div class="event"><span>'+e.icon+'</span><div><b>'+e.label+'</b><small>'+e.sub+'</small></div><time>'+fmt(e.date)+'</time></div>').join(''):'<p>No twilight crossings in this period at this latitude.</p>';$('sky-link').href='https://www.heavens-above.com/skychart2.aspx?lat='+s.lat+'&lng='+s.lon;const dark=s.hours.slice(0,horizon).filter(h=>h.sun<-18);$('highlight-context').textContent=dark.length?'First dark forecast hour: '+fmt(dark[0].date)+'. Use the linked sky chart’s date/time controls for your selected dark hour.':'No astronomical dark forecast hours in this period. Check local twilight before planning.';renderHours()}
function renderHours(){if(!state)return;$('condensation-method').textContent=units==='imperial'?'* Dew/frost flags are inferred equipment-risk indicators: humidity ≥85% or air within 5.4°F of dew point; frost possible when air is ≤37.4°F, otherwise dew possible. Optics may cool below air temperature. No badge does not guarantee dry optics; missing inputs leave risk unavailable (null).':'* Dew/frost flags are inferred equipment-risk indicators: humidity ≥85% or air within 3°C of dew point; frost possible when air is ≤3°C, otherwise dew possible. Optics may cool below air temperature. No badge does not guarantee dry optics; missing inputs leave risk unavailable (null).';const rows=state.hours.slice(0,horizon).map((h,i)=>({...h,i})).filter(h=>!nightOnly||h.sun<-18);$('hours').innerHTML=rows.length?rows.map(h=>'<button class="hour viewing-'+NightwatchScore.band(h.score)+' '+(selected===h.i?'selected':'')+'" data-hour="'+h.i+'" aria-label="'+escapeText(fmt(h.date)+', cloud cover '+display(h.cloud,'%')+', '+precipAmount(h.precip)+' precipitation, '+display(h.rain,'%')+' chance'+', inferred viewing score '+display(h.score)+', '+(NightwatchScore.quality(h.score)||'unavailable')+(NightwatchWeather.condensation(h).kind?', '+NightwatchWeather.condensation(h).kind+' possible':''))+'"><span>'+fmt(h.date,{weekday:'short',day:'numeric'})+'</span><span>'+fmt(h.date,{hour:'numeric'})+'</span><b>'+(h.sun>=0?'☀':h.cloud===null?'?':h.cloud>65?'☁':'☾')+'</b><strong>'+display(h.cloud,'%')+'</strong><span>cloud cover</span><span>'+temperature(h.temp)+'</span><span class="hour-precip"><span>Precip.</span><strong>'+precipAmount(h.precip)+'</strong><small>'+display(h.rain,'%')+' chance</small></span><span class="hour-score"><span class="hour-quality">'+(NightwatchScore.quality(h.score)||'Unavailable')+'</span>'+display(h.score)+'/100*</span>'+NightwatchWeather.badge(h)+'</button>').join(''):'<p>No astronomical dark forecast hours in this period.</p>';if(rows.length&&!rows.some(h=>h.i===selected))selected=rows[0].i;renderSelected();document.querySelectorAll('[data-hour]').forEach(el=>el.onclick=()=>{selected=Number(el.dataset.hour);renderHours()})}
function renderSelected(){const h=state.hours[selected];window.NightwatchMap?.update({lat:state.lat,lon:state.lon,name:state.name,zone:state.zone,date:h.date,units});$('score').textContent=display(h.score);$('score').setAttribute('data-quality',NightwatchScore.band(h.score));$('rating').textContent=finite(h.score)?NightwatchScore.quality(h.score)+' · inferred*':'null · required inputs missing';$('cloud').textContent=display(h.cloud,'%');$('wind').textContent=wind(h.wind);$('humidity').textContent=display(h.humidity,'%');$('dewpoint').textContent=temperature(h.temp)+' / '+temperature(h.dew);const spread=finite(h.temp)&&finite(h.dew)?h.temp-h.dew:null;$('dewspread').textContent='Air / dew point · spread '+display(finite(spread)?units==='imperial'?spread*9/5:spread:null,units==='imperial'?'°F':'°C',1);const advice=dewAdvice(h);$('dew-title').textContent='Dew heater: '+(advice.use===null?'null':advice.use?'recommended':'not indicated by thresholds');$('dew-advice').textContent=fmt(h.date)+' · '+advice.text;$('detail').textContent=fmt(h.date)+' · '+(h.sun>=0?'Daylight':h.sun<-18?'Astronomical darkness':'Twilight')+' · '+display(h.cloud,'%')+' cloud · '+temperature(h.temp)+' · '+display(h.humidity,'%')+' humidity · Dew point '+temperature(h.dew)+' · '+wind(h.wind)+' wind · '+precipAmount(h.precip)+' precipitation · '+display(h.rain,'%')+' precipitation chance · Moon '+(h.moonAlt>0?'above':'below')+' horizon';document.querySelectorAll('[data-hour]').forEach(el=>el.classList.toggle('selected',Number(el.dataset.hour)===selected));renderCMC();renderImaging();clearTimeout(cmcTimer);if(!h.cmc)cmcTimer=setTimeout(()=>loadCMC(state,h),300)}
$('search').onsubmit=async e=>{e.preventDefault();const term=$('city').value.trim();if(term.length<2){$('status').textContent='Enter at least two letters of a city name.';return;}$('status').textContent='Searching locations…';try{const d=await json('https://geocoding-api.open-meteo.com/v1/search?name='+encodeURIComponent(term)+'&count=6&language=en&format=json');$('results').replaceChildren();if(!d.results?.length){$('status').textContent='No matching cities. Try a nearby town or another spelling.';return;}d.results.forEach(r=>{const name=[r.name,r.admin1,r.country].filter(Boolean).join(', ');const button=document.createElement('button');button.textContent=name;button.onclick=()=>{$('results').replaceChildren();$('city').value='';load(r.latitude,r.longitude,name)};$('results').append(button)});$('status').textContent='Choose a location above.'}catch{$('status').textContent='Location search is unavailable. Please try again.'}};
$('locate').onclick=()=>{if(!navigator.geolocation){$('status').textContent='Device location is unavailable. Search for a city instead.';return;}$('status').textContent='Waiting for your location…';navigator.geolocation.getCurrentPosition(p=>load(p.coords.latitude,p.coords.longitude,'Your location · '+p.coords.latitude.toFixed(2)+'°, '+p.coords.longitude.toFixed(2)+'°'),()=>{$('status').textContent='Location access was unavailable. Search for a city to see your forecast.'},{timeout:12000,maximumAge:300000})};$('all').onclick=()=>{nightOnly=false;$('all').classList.add('active');$('night').classList.remove('active');renderHours()};$('night').onclick=()=>{nightOnly=true;$('night').classList.add('active');$('all').classList.remove('active');renderHours()};$('red').onclick=()=>{$('red').setAttribute('aria-pressed',document.body.classList.toggle('red'))};$('method').onclick=()=>$('info').showModal();$('close').onclick=()=>$('info').close();document.addEventListener('keydown',e=>{if(e.key==='Escape')$('results').replaceChildren()});document.querySelectorAll('[data-range]').forEach(button=>button.onclick=()=>{imagingRun++;if(state)state.imagingRunning=false;horizon=Number(button.dataset.range);if(selected>=horizon)selected=0;document.querySelectorAll('[data-range]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-selected',String(b===button))});render()});
try{units=NightwatchWeather.preference(localStorage.getItem('nightwatch-units'))}catch{}$('units').value=units;$('units').onchange=()=>{units=$('units').value;try{localStorage.setItem('nightwatch-units',units)}catch{}if(state)renderHours()};
let saved;try{saved=JSON.parse(localStorage.getItem('nightwatch-location'))}catch{}if(saved&&Number.isFinite(saved.lat)&&Number.isFinite(saved.lon))load(saved.lat,saved.lon,saved.name);else load(35.1983,-111.6513,'Flagstaff, Arizona · Example location');

function renderCMC(){if(!state)return;const h=state.hours[selected],result=h.cmc;for(const field of ['seeing','transparency']){const item=result?.[field],d=item?.data;$(field).textContent=d?String(d.value):'null';$(field+'-source').textContent=d?(d.label||'CMC index')+' · Valid '+fmt(new Date(d.time)):(item?.reason||'Loading CMC forecast…');}const records=['seeing','transparency'].map(k=>result?.[k]?.data).filter(Boolean);$('cmc-status').textContent=!result?'Loading CMC/ECCC RDPS for '+fmt(h.date)+'…':records.length?'Source: ECCC/CMC RDPS · Valid '+fmt(h.date)+' · '+records.map(d=>'model run '+new Date(d.reference).toISOString()+(d.coordinates?' · grid '+d.coordinates.join(', '):'')).filter((v,i,a)=>a.indexOf(v)===i).join(' / ')+' · Provider indices, not arcseconds.':'CMC data unavailable for this location/hour; values remain null.';}
async function loadCMC(s,h){
 if(h.cmc)return h.cmc;
 if(h.cmcPromise)return h.cmcPromise;
 h.cmcPromise=(async()=>{const results=await Promise.allSettled(['seeing','transparency'].map(field=>CMC.point(field,s.lat,s.lon,h.date)));h.cmc=Object.fromEntries(['seeing','transparency'].map((field,i)=>[field,results[i].status==='fulfilled'?results[i].value:{data:null,reason:'CMC request failed or timed out; value is null.'}]));if(state===s){if(state.hours[selected]===h)renderCMC();renderImaging();}return h.cmc;})();
 try{return await h.cmcPromise}finally{delete h.cmcPromise}
}

function renderImaging(){if(state)NightwatchImagingUI.render(state,horizon,selected,fmt,i=>{selected=i;if(nightOnly&&state.hours[i].sun>=-18){nightOnly=false;$('all').classList.add('active');$('night').classList.remove('active');}renderHours()})}
$('imaging-analyze').onclick=async()=>{
 if(!state)return;const s=state,range=horizon,run=++imagingRun;s.imagingRunning=true;renderImaging();
 try{for(const h of s.hours.slice(0,range).filter(NightwatchImaging.isDark)){if(run!==imagingRun||state!==s||horizon!==range)break;await loadCMC(s,h);}}
 finally{if(run===imagingRun){s.imagingRunning=false;if(state===s)renderImaging();}}
};
$('imaging-cancel').onclick=()=>{imagingRun++;if(state){state.imagingRunning=false;renderImaging();}};


$('score-method').onclick=()=>$('info').showModal();

function renderLocalSky(){if(!state)return;const readings=LocalSky.read(state.lat,state.lon),provider=state.lightPollution?.data;const bortle=readings.bortle??provider?.bortleClass??null,sqm=readings.sqm??provider?.sqm??null;$('bortle').textContent=bortle===null?'null':String(bortle);$('sqm').textContent=display(sqm,'',2);$('bortle-source').textContent=readings.bortle!==null?'User supplied · not independently verified':bortle!==null?'DarkSkySites · provider-derived class':'No available local value';$('sqm-source').textContent=readings.sqm!==null?'User supplied · not independently verified':sqm!==null?'DarkSkySites · modeled zenith brightness':'No available local value';$('pollution-location').textContent=state.name+' · '+state.lat.toFixed(6)+', '+state.lon.toFixed(6);$('pollution-map').href=LocalSky.mapURL(state.lat,state.lon);$('bortle-input').value=readings.bortle??'';$('sqm-input').value=readings.sqm??'';$('readings-status').textContent='';document.querySelectorAll('[data-bortle]').forEach(el=>el.classList.toggle('selected',Number(el.dataset.bortle)===bortle));$('pollution-status').textContent=provider?'Provider dataset: '+(provider.dataset?.id??'null')+' · Quality: '+(provider.quality?.status??'null')+' · Coverage verified: '+(provider.quality?.coverageVerified===true?'yes':'no')+(provider.dataset?.fallbackUsed?' · Older dataset used: '+(provider.dataset.fallbackReason??'reason not supplied'):'')+(provider.notice?' · '+provider.notice:'')+(provider.fetchedAt?' · Retrieved '+fmt(new Date(provider.fetchedAt)):''):state.lightPollution?.message||'Checking automatic light-pollution lookup…';}
async function loadLocalSky(s){try{s.lightPollution=await LocalSky.lookup(s.lat,s.lon)}catch(error){s.lightPollution={configured:true,data:null,message:error.message+' Values remain null unless you supplied local readings.'}}if(state===s)renderLocalSky()}
$('sky-readings-form').onsubmit=e=>{e.preventDefault();if(!state)return;try{LocalSky.save(state.lat,state.lon,$('bortle-input').value,$('sqm-input').value);renderLocalSky();$('readings-status').textContent='Known local readings saved for this location.'}catch(error){$('readings-status').textContent=error.message}};
$('clear-readings').onclick=()=>{if(!state)return;try{LocalSky.clear(state.lat,state.lon);renderLocalSky();$('readings-status').textContent='Local readings cleared; unavailable values remain null.'}catch{$('readings-status').textContent='Browser storage is unavailable.'}};
